create function pg_temp.reject_planning_audit() returns trigger language plpgsql as $$begin
 if new.action in ('timplan_cell_changed','timplan_read') then raise exception 'Synthetic audit failure' using errcode='55000'; end if; return new;
end $$;
create trigger planning_audit_failure before insert on public.security_events for each row execute function pg_temp.reject_planning_audit();
select throws_ok($q$select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',2,'matematik',0,777)$q$,'55000',null,'audit failure stops entire command');
select is((select hours[1]::int from public.timplan_cells where timplan_id='55003000-0000-4000-8000-000000000050' and row_id='matematik'),100,'hours rolled back with failed audit');
select is((select revision from public.timplans where id='55003000-0000-4000-8000-000000000050'),2,'revision rolled back with failed audit');
select throws_ok($q$select public.phase5_read_timplan('55003000-0000-4000-8000-000000000050')$q$,'55000',null,'read returns nothing when audit fails');
drop trigger planning_audit_failure on public.security_events;
select is(has_function_privilege('anon','public.phase5_read_timplan(uuid)','EXECUTE'),false,'anon cannot execute phase5_read_timplan');
