select is(has_function_privilege('skolplattform_worker','public.phase5_timplan_scope(uuid,boolean)','EXECUTE'),false,'skolplattform_worker cannot execute phase5_timplan_scope');
select is(has_function_privilege('skolplattform_worker','public.phase5_timplan_audit(uuid,text)','EXECUTE'),false,'skolplattform_worker cannot execute phase5_timplan_audit');
savepoint planning_outer;
select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',2,'matematik',0,0);
select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',3,'matematik',2,2000);
do $$begin
 if not exists(select 1 from public.timplan_cells where timplan_id='55003000-0000-4000-8000-000000000050' and row_id='matematik' and hours[1]=0 and hours[3]=2000) then raise exception 'Boundary write failed'; end if;
end $$;
rollback to planning_outer;
select is((select revision from public.timplans where id='55003000-0000-4000-8000-000000000050'),2,'outer rollback restores revision');
select is((select hours[1]::int from public.timplan_cells where timplan_id='55003000-0000-4000-8000-000000000050' and row_id='matematik'),100,'outer rollback restores hours');
select is((select count(*) from public.security_events where object_id='55003000-0000-4000-8000-000000000050' and action='timplan_cell_changed'),2::bigint,'outer rollback removes its successful audit');
select ok((select timplan_id='55003000-0000-4000-8000-000000000054' and column_id='ak4' from public.class_timplans where unit_id='55003000-0000-4000-8000-000000000030' and class_name='SYNTETISK'),'existing explicit class binding stays unchanged');
select ok((select status='faststalld' and decided_on=public.app_today() and revision=0 and version=2 from public.timplans where id='55003000-0000-4000-8000-000000000054'),'existing decided version unchanged');
update public.offerings set grades=null where id='55003000-0000-4000-8000-000000000040';
update public.timplan_cells set hours=array[100,100,100,100,100,100,100,100,100]::smallint[] where timplan_id='55003000-0000-4000-8000-000000000050' and row_id='matematik';
select lives_ok($q$select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',2,'matematik',8,0)$q$,'missing grades use nine standard columns');
update public.offerings set grades='{}'::smallint[] where id='55003000-0000-4000-8000-000000000040';
select lives_ok($q$select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',3,'matematik',0,2000)$q$,'empty grades use standard columns and max hours');
update public.offerings set grades=array[9,1,4]::smallint[] where id='55003000-0000-4000-8000-000000000040';
select lives_ok($q$select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',4,'no',1,12)$q$,'NO stage follows stored grade order');
select throws_ok($q$select public.phase5_change_timplan_cell('55003000-0000-4000-8000-000000000050',5,'no',0,12)$q$,'22023',null,'NO high stage rejected in reordered columns');
select * from finish();
rollback;
